s="panel grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><label><span class="label">Sale Discount</span><input type="number" step=".01" min="0" name="discount" value="0" class="field" data-total></label><label><span class="label">Tax</span><input type="number" step=".01" min="0" name="tax" value="0" class="field" data-total></label><label><span class="label">Paid Amount *</span><input type="number" step=".01" min="0" name="paid_amount" value="0" class="field" data-total required></label><label><span class="label">Payment Method *</span><select name="payment_method" class="field">@foreach(['Cash','Card','Bank Transfer','Cheque','QR','Credit/Due'] as $method)<option>{{ $method }}</option>@endforeach</select></label><label class="sm:col-span-2"><span class="label">Receiving Account</span><select name="account_id" class="field"><option value="">Select account</option>@foreach($accounts as $account)<option value="{{ $account->id }}">{{ $account->name }}</option>@endforeach</select></label><div class="rounded-xl bg-slate-950 p-4 text-white"><small>Grand Total</small><b class="block text-xl" data-grand>Rs. 0.00</b></div><div class="rounded-xl bg-red-50 p-4 text-red-700"><small>Due Amount</small><b class="block text-xl" data-due>Rs. 0.00</b></div></section><div class="flex flex-wrap justify-end gap-2"><button type="reset" class="btn-secondary">Clear Cart</button><button class="btn-secondary" name="action" value="print">Save & Print</button><button class="btn-secondary" name="action" value="sms">Save & Send SMS</button><button class="btn-primary">Save Sale</button></div></div><aside class="space-y-5"><div class="panel"><h3 class="font-extrabold">Cart Summary</h3><p class="mt-2 text-sm text-slate-400">Stock is validated and deducted only when the sale is saved.</p></div><div class="panel border-orange-100 bg-orange-50"><h3 class="font-extrabold text-orange-700">Low Stock Warning</h3><p class="mt-2 text-sm text-orange-700">{{ $stats['low'] }} product(s) currently need stock attention.</p></div><div class="panel"><h3 class="font-extrabold">Recent Sales</h3><div class="mt-3 space-y-2">@forelse($recent as $sale)<div class="flex justify-between text-sm"><span>{{ $sale->number }}</span><b>Rs. {{ number_format($sale->total,2) }}</b></div>@empty<p class="text-sm text-slate-400">New sales will appear here.</p>@endforelse</div></div></aside></form>
