<template id="parts-row"><tr><td class="min-w-[270px]"><input type="search" list="parts-products" class="field" data-search placeholder="Product, SKU or barcode" required><input type="hidden" data-id><input type="hidden" data-batch-id><div data-batch-msg class="mt-1 text-xs text-indigo-600 font-bold empty:hidden"></div></td><td data-sku>—</td><td data-stock>0</td><td><input type="number" min=".01" step=".01" value="1" class="field !w-24" data-qty required></td><td><input type="number" min="0" step=".01" class="field !w-28" data-price required></td><td><input type="number" min="0" step=".01" value="0" class="field !w-24" data-discount></td><td class="font-black" data-line>Rs. 0.00</td><td><button type="button" class="rounded-lg bg-red-50 px-3 py-2 font-black text-red-600" data-remove>×</button></td></tr></template><datalist id="parts-products">@foreach($productOptions as $option)<option value="{{ $option['label'] }}"></option>@endforeach</datalist>
<script>(()=>{const form=document.getElementById('parts-sale-form');const products={{ Illuminate\Support\Js::from($productOptions) }};const cart=form.querySelector('[data-cart]');const template=document.getElementById('parts-row');const modal=document.getElementById('batch-modal');const list=document.getElementById('batch-list');const tpl=document.getElementById('batch-item-tpl');const money=n=>'Rs. '+Number(n||0).toFixed(2);const calc=()=>{let sub=0;cart.querySelectorAll('tr').forEach(row=>{const line=Math.max(0,(+row.querySelector('[data-qty]').value||0)*(+row.querySelector('[data-price]').value||0)-(+row.querySelector('[data-discount]').value||0));row.querySelector('[data-line]').textContent=money(line);sub+=line});const total=Math.max(0,sub-(+form.discount.value||0)+(+form.tax.value||0));form.querySelector('[data-grand]').textContent=money(total);form.querySelector('[data-due]').textContent=money(Math.max(0,total-(+form.paid_amount.value||0)))};const renumber=()=>cart.querySelectorAll('tr').forEach((row,i)=>{row.querySelector('[data-id]').name=`items[${i}][product_id]`;row.querySelector('[data-batch-id]').name=`items[${i}][stock_batch_id]`;row.querySelector('[data-qty]').name=`items[${i}][quantity]`;row.querySelector('[data-price]').name=`items[${i}][unit_price]`;row.querySelector('[data-discount]').name=`items[${i}][discount]`});const add=()=>{const row=template.content.firstElementChild.cloneNode(true);const search=row.querySelector('[data-search]');const sync=()=>{const p=products.find(p=>p.label.toLowerCase()===search.value.trim().toLowerCase());row.querySelector('[data-id]').value=p?.id||'';row.querySelector('[data-batch-id]').value='';row.querySelector('[data-batch-msg]').textContent='';search.setCustomValidity(search.value&&!p?'Choose a product from suggestions.':'');row.querySelector('[data-sku]').textContent=p?.sku||'—';const storeId=+form.querySelector('[data-store]').value;const stock=p?.stocks.find(s=>s.store_id===storeId)?.quantity||0;row.querySelector('[data-stock]').textContent=stock;row.querySelector('[data-price]').value=p?.price??'';const batches=p?.batches?.filter(b=>b.store_id===storeId)||[];if(batches.length>1){list.innerHTML='';batches.forEach(b=>{const el=tpl.content.cloneNode(true);const radio=el.querySelector('input');radio.value=b.id;el.querySelector('[data-batch-no]').textContent=b.batch_no;el.querySelector('[data-cost]').textContent=money(b.cost);el.querySelector('[data-selling]').textContent=money(b.selling);el.querySelector('[data-qty]').textContent=b.qty;radio.addEventListener('change',()=>{row.querySelector('[data-batch-id]').value=b.id;row.querySelector('[data-price]').value=b.selling;row.querySelector('[data-batch-msg]').textContent=`Batch: ${b.batch_no}`;modal.close();calc();});list.appendChild(el);});modal.showModal();}else if(batches.length===1){row.querySelector('[data-batch-id]').value=batches[0].id;row.querySelector('[data-price]').value=batches[0].selling;row.querySelector('[data-batch-msg]').textContent=`Batch: ${batches[0].batch_no}`;}calc()};search.addEventListener('input',sync);row.querySelectorAll('input').forEach(i=>i.addEventListener('input',calc));row.querySelector('[data-remove]').addEventListener('click',()=>{row.remove();renumber();calc()});cart.append(row);renumber();calc()};form.querySelector('[data-add]').addEventListener('click',add);form.querySelector('[data-scan]').addEventListener('click',()=>{if(!cart.children.length)add();cart.lastElementChild.querySelector('[data-search]').focus()});form.querySelectorAll('[data-total]').forEach(i=>i.addEventListener('input',calc));const mode=form.querySelector('[data-mode]');mode.addEventListener('change',()=>{form.querySelector('[data-existing]').classList.toggle('hidden',mode.value!=='existing');form.querySelector('[data-new]').classList.toggle('hidden',mode.value!=='new')});add();})();</script></div></x-layouts::app>
